#!/usr/bin/env bash
set +e

# Github
source "$BASEPATH/.github/scripts/Utility/Github.sh"
Github "$BASEPATH/SDL_mixer" "https://github.com/libsdl-org/SDL_mixer.git" ""

# Environment
INSTALLPATH="$BASEPATH/SDL_mixer/install_output"
BUILDPATH="$BASEPATH/SDL_mixer/build_output"
mkdir -p "$BUILDPATH"
mkdir -p "$INSTALLPATH"
cd "$BUILDPATH"

# SDL_mixer
"${ARGS[@]}" \
  -DSDLMIXER_WAVE=ON \
  -DSDLMIXER_MP3_DRMP3=ON \
  -DSDLMIXER_VORBIS_STB=ON \
  -DSDLMIXER_VORBIS_VORBISFILE=OFF \
  -DSDLMIXER_VORBIS_TREMOR=OFF \
  -DSDLMIXER_MIDI_TIMIDITY=OFF \
  -DSDLMIXER_MIDI_FLUIDSYNTH=OFF \
  -DSDLMIXER_FLAC_LIBFLAC=OFF \
  -DSDLMIXER_FLAC_DRFLAC=OFF \
  -DSDLMIXER_MP3_MPG123=OFF \
  -DSDLMIXER_GME_SHARED=OFF \
  -DSDLMIXER_MOD_XMP=OFF \
  -DSDLMIXER_WAVPACK=OFF \
  -DSDLMIXER_AIFF=OFF \
  -DSDLMIXER_MIDI=OFF \
  -DSDLMIXER_OPUS=OFF \
  -DSDLMIXER_VOC=OFF \
  -DSDLMIXER_GME=OFF \
  -DSDLMIXER_AU=OFF \
  -DSDLMIXER_TESTS=OFF \
  -DSDLMIXER_EXAMPLES=OFF \
  -DSDLMIXER_VENDORED=ON \
  -DSDLMIXER_DEPS_SHARED=OFF \
  -DCMAKE_BUILD_TYPE=MinSizeRel \
  -DCMAKE_POLICY_VERSION_MINIMUM=3.5 \
  -DCMAKE_INSTALL_PREFIX="$INSTALLPATH"

cmake --build . --config MinSizeRel
cmake --install . --config MinSizeRel

echo "Output files...."
find "$INSTALLPATH"